import itertools
from reduce import reduce

def sat(inst):
    m=inst['num_vars']
    for a in itertools.product([0,1],repeat=m):
        if all(any((a[abs(l)-1]==1) if l>0 else (a[abs(l)-1]==0) for l in cl) for cl in inst['clauses']):
            return True
    return False

def min_dom(inst):
    n=inst['n']; adj=[0]*n
    for u,v in inst['edges']:
        adj[u]|=1<<v; adj[v]|=1<<u
    closed=[adj[v]|(1<<v) for v in range(n)]
    best=[n]
    def rec(dom,ch):
        if ch>=best[0]: return
        if dom==(1<<n)-1: best[0]=ch; return
        und=[v for v in range(n) if not (dom>>v)&1]
        v=max(und,key=lambda x:bin(closed[x]).count('1'))
        opts=[v]+[w for w in range(n) if (adj[v]>>w)&1]
        for c in opts: rec(dom|closed[c],ch+1)
    rec(0,0)
    return best[0]

inst={'num_vars': 4, 'clauses': [[2, 3, 4], [-1, 3, -4], [-1, -2, -4], [1, 3, -4], [1, -3, -4], [-1, -2, -3], [1, 2, 4], [1, 2, -3], [-1, 3, 4], [-1, 2, -3], [-2, -3, 4], [-2, 3, 4]]}
print('sat', sat(inst))
r=reduce(inst); print('k',r['k'],'min_dom',min_dom(r))

# minimize: remove clauses while keeping unsat and counterexample
clauses=[list(c) for c in inst['clauses']]
changed=True
while changed:
    changed=False
    for i in range(len(clauses)):
        trial=[c for j,c in enumerate(clauses) if j!=i]
        ti={'num_vars':4,'clauses':trial}
        if not sat(ti):
            tr=reduce(ti)
            if min_dom(tr)<=tr['k']:
                clauses=trial; changed=True; break
print('minimal counterexample clauses:', clauses)
print('num clauses', len(clauses))
ti={'num_vars':4,'clauses':clauses}
print('sat', sat(ti), 'red k', reduce(ti)['k'], 'min_dom', min_dom(reduce(ti)))
""}

